import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

 const [data, setData] = useState({
  income: "",
  incomeRange: "",
  spendingRange: "",
  savingRange: "",
  categories: [],
  priorities: [],
  limits: {}
});
  return (
    <>
      {/* LOGIN */}
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {/* INCOME */}
      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData({ ...data, income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {/* QUESTIONNAIRE */}
      {step === "questionnaire" && (
        <Questionnaire
          data={data}   // ✅ PASS DATA
          onNext={(answers) => {
            setData({
              ...data,
              incomeRange: answers.incomeRange,
              spendingRange: answers.spendingRange,
              savingRange: answers.savingRange
            });
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {/* PRIORITY */}
      {step === "priority" && (
        <SpendingPriority
          data={data}   // ✅ PASS DATA
          onNext={(priorities) => {
            setData({ ...data, priorities });
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {/* BUDGET */}
      {step === "budget" && (
        <BudgetLimits
          data={data}   // ✅ PASS DATA
          selectedCategories={data.priorities}
          onNext={(limits) => {
            setData({ ...data, limits });
            setStep("preview");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {/* PREVIEW */}
      {step === "preview" && (
        <Preview
          data={data}
          onEdit={() => setStep("income")}
          onConfirm={() => setStep("dashboard")}
        />
      )}

      {/* DASHBOARD */}
      {step === "dashboard" && (
        <Dashboard />
      )}
    </>
  );
}

export default App;
